static void note_wide(AvraArray* a, int64_t cap, void* pusher) {
    if (cap < g_wide_cells || pusher == NULL) return;
    Site* w = site_in(g_wide, &g_wide_slots, pusher);
    if (w == NULL) return;
    w->live += (int64_t)buf_bytes(cap, avra_packed(a));
    w->count++;
