}

static void report_wide(intptr_t slide) {
    for (int shown = 0; shown < 20; shown++) {
        Site* top = NULL;
        for (int i = 0; i < SITES; i++) {
            if (g_wide[i].site && g_wide[i].live > 0 && (top == NULL || g_wide[i].live > top->live)) top = &g_wide[i];
