                (unsigned long long)((uintptr_t)top->site - (uintptr_t)slide), (long long)(top->live >> 20),
                (long long)top->count, (unsigned long long)((uintptr_t)top->sample - (uintptr_t)slide));
        top->live = -top->live;
    }
}

