// proves: an enum whose widest variant carries two words rides registers as its tag and both words —
// built, matched, passed and answered; laid into a record's box, a map's values and a nullable, its
// absence the spare tag. One carrying only scalars lays its three words in place in a list — built by
// a literal, a comprehension, pushes and a `const`; read by index, a walk, `find`, `filter` and a list
// pattern; written whole, popped, sliced past any length and concatenated; held by two holders, the
// writer opening its own. One carrying a pointer in either word keeps one cell an element, each word
// counted by its own mask. One whose payloads are one-word records rides as its words.
enum Spot {
    Here(id: int)
    Field(owner: int, index: int)
    Gone
}
enum Named {
    Name(s: string, n: int)
    Pair(a: string, b: string)
    Blank
}
type Id = { index: int }
enum Loc {
    One(id: Id)
    Two(a: Id, b: Id)
}
type Holder = { tag: string, spot: Spot, named: Named }

const START: List<Spot> = [Spot.Here(1), Spot.Field(2, 3), Spot.Gone]

fn sp(s: Spot) -> string {
    match s { .Here(id) -> "h${id}", .Field(o, i) -> "f${o}.${i}", .Gone -> "g" }
}

fn sps(xs: List<Spot>) -> string { xs.fold("", (at: string, s: Spot) -> at + sp(s)) }

fn nm(n: Named) -> string {
    match n { .Name(s, k) -> "${s}${k}", .Pair(a, b) -> "${a}+${b}", .Blank -> "_" }
}

fn nms(xs: List<Named>) -> string { xs.fold("", (at: string, n: Named) -> at + nm(n) + ";") }

fn lc(l: Loc) -> string {
    match l { .One(id) -> "${id.index}", .Two(a, b) -> "${a.index}-${b.index}" }
}

fn shifted(s: Spot, by: int) -> Spot {
    match s {
        .Here(id) -> Spot.Here(id + by),
        .Field(o, i) -> Spot.Field(o + by, i + by),
        .Gone -> Spot.Gone,
    }
}

fn owner_of(s: Spot) -> int {
    match s { .Field(o, _) -> o, rest -> 0 }
}

/// One body for every `T`: the list doubled, then turned by swaps in place.
fn turned<T>(xs: List<T>) -> List<T> {
    mut out = xs.concat(xs)
    mut i = 0
    mut j = out.length - 1
    while i < j {
        let t = out[i]
        out[i] = out[j]
        out[j] = t
        i = i + 1
        j = j - 1
    }
    out
}

// built, matched, passed and answered
let a = Spot.Field(4, 5)
println("A ${sp(a)} ${sp(shifted(a, 10))} ${sp(shifted(Spot.Here(1), 1))} ${sp(Spot.Gone)}")

// a list of scalar ones, built every way
let lit = [Spot.Here(1), Spot.Field(2, 3), Spot.Gone]
let comp = [Spot.Field(i, i * i) for i in 0..4]
mut pushed: List<Spot> = []
// LICENSED loops.push_loop: the pushes ARE the attack — an empty strided list grown three words an element past every buffer class
for i in 0..30 { pushed.push(if i % 3 == 0 { Spot.Here(i) } else { Spot.Field(i, -i) }) }
println(
    "B ${sps(lit)} ${sps(comp)} ${pushed.length} ${sp(pushed[29])} ${sp(pushed[27])} ${sps(START)}",
)

// read, written, popped, sliced and concatenated
mut edit = [Spot.Here(1), Spot.Here(2), Spot.Here(3)]
edit[1] = Spot.Field(7, 8)
let last = edit.pop()
edit.push(Spot.Gone)
let cut = comp.slice(1, 1000000000000)
let joined = edit.concat(cut)
mut owners = 0
for s in pushed { owners = owners + owner_of(s) }
let picked = match comp { [x, y, ..rest] -> "${sp(x)}${sp(y)}+${rest.length}", _ -> "short" }
let missing = if comp.find(owner_of(it) == 9) == null { "none" } else { "some" }
println(
    "C ${sps(edit)} ${sp(last)} ${sps(cut)} ${joined.length} ${sp(joined[2])} ${owners} ${picked} ${sp(comp.find(owner_of(it) == 2)!)} ${missing}",
)

// two holders: the one that writes opens its own
let first = [Spot.Here(1), Spot.Here(2)]
mut second = first
second[0] = Spot.Field(5, 5)
second.push(Spot.Gone)
println("D ${sps(first)} ${sps(second)}")

// a pointer in either word: a list's cells, a record's box, a map's values, a nullable, one generic body
let ns = [Named.Name("a", 1), Named.Pair("b", "c"), Named.Blank]
mut more = ns
more.push(Named.Pair("x" + "y", "z"))
more[0] = Named.Name("q" + "r", 9)
let held = Holder { tag: "t", spot: Spot.Field(1, 2), named: Named.Pair("m", "n") }
mut rewritten = held
rewritten.named = Named.Name("w", 3)
rewritten.spot = Spot.Gone
let byname: Map<string, Named> = {"k": Named.Pair("u", "v")}
let absent: Named? = null
let present: Named? = Named.Name("h", 5)
println(
    "E ${nms(ns)} ${nms(more)} ${sp(held.spot)}${nm(held.named)} ${sp(rewritten.spot)}${nm(rewritten.named)} ${nm(byname.get("k")!)} ${if absent == null { "absent" } else { "present" }} ${nm(present!)} ${nms(turned(ns))}",
)

// a const's elements mapped, filtered by variant
let moved = START.map(shifted(it, 100))
println("F ${sps(moved)} ${sps(lit.filter(it is .Field))} ${START.length}")

// payloads that are one-word records
let locs = [Loc.One(Id { index: 1 }), Loc.Two(Id { index: 2 }, Id { index: 3 })]
println("G ${locs.map(lc(it)).join(",")}")
